import sys
import math

class Reader:
    def __init__(self):
        self.tokens = []
        self.input = sys.stdin.read().split()
        self.index = 0

    def next(self):
        while self.index >= len(self.tokens):
            if self.index >= len(self.input):
                return ''
            self.tokens = self.input[self.index:].split()
            self.index = 0
        token = self.tokens[self.index]
        self.index += 1
        return token

    def nextInt(self):
        return int(self.next())

    def nextLong(self):
        return int(self.next())

    def nextStr(self):
        return self.next()

def main():
