        for j in range(1, i + 1):
            nCr[i][j] = (nCr[i - 1][j] + nCr[i - 1][j - 1]) % mod

    totalRes = 0
    for i in range(n - 1):
        cnt = n - i
        pre = n - cnt
        comb = (nCr[n][pre] * fact[pre]) % mod
        lastDP = dp[cnt - 2] if cnt - 2 >= 0 else [0] * len(dp[0])
        ssum = 0
        totalSum = 0
        for j in range(2, len(dp[0])):
